export const getTechIcon = (type: string, className = "") => {
  switch (type.toLowerCase()) {
    case "html":
      return <HtmlIcon className={className} />;
    case "css":
      return <CssIcon className={className} />;
    case "tailwind":
      return <TailwindIcon className={className} />;
    case "javascript":
      return <JavascriptIcon className={className} />;
    case "typescript":
      return <TypescriptIcon className={className} />;
    case "react":
      return <ReactIcon className={className} />;
    case "nextjs":
    case "next.js":
      return <NextjsIcon className={className} />;
    case "vue":
    case "vue.js":
      return <VueIcon className={className} />;
    case "nuxt":
    case "nuxt.js":
      return <NuxtIcon className={className} />;
    case "laravel":
      return <LaravelIcon className={className} />;
    case "git":
      return <GitIcon className={className} />;
    case "mysql":
      return <MysqlIcon className={className} />;
    case "docker":
      return <DockerIcon className={className} />;
    case "php":
      return <PhpIcon className={className} />;
    case "kotlin":
      return <KotlinIcon className={className} />;
    case "python":
      return <PythonIcon className={className} />;
    case "fastapi":
      return <FastapiIcon className={className} />;
    default:
      return <ReactIcon className={className} />;
  }
};

